589	function execRemote(
590	  conn: Client,
591	  cmd: string,
592	  timeoutMs: number
593	): Promise<{ code: number; stdout: string; stderr: string }> {
594	  return new Promise((resolve, reject) => {
595	    conn.exec(cmd, (err, stream: ClientChannel) => {
596	      if (err) return reject(err);
597	      let stdout = "";
598	      let stderr = "";
599	      const timer = setTimeout(() => {
600	        try {
601	          stream.close();
602	        } catch {
603	          /* ignore */
604	        }
605	        reject(new Error("remote command timed out"));
606	      }, timeoutMs);
607	      stream
608	        .on("close", (code: number) => {
609	          clearTimeout(timer);
610	          resolve({ code: code ?? 0, stdout, stderr });
611	        })
612	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
613	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
614	    });
615	  });
616	}
