622	 * with its reason in `stderr`. Every best-effort step uses this so one failed
623	 * probe can never abort the whole migration.
624	 */
625	function sh(conn: Client, cmd: string, timeoutMs: number = SETUP_TIMEOUT_MS): Promise<ExecResult> {
626	  return execRemote(conn, cmd, timeoutMs).catch((e) => ({
627	    code: 1,
628	    stdout: "",
629	    stderr: String(e?.message ?? e),
630	  }));
631	}
