import { test } from "node:test";
import assert from "node:assert/strict";
import { planConsolidation, inventoryFromScan, consolidationBlockers, type SourceInventory } from "../lib/migrate-consolidate.ts";

const src = (label: string, apps: SourceInventory["apps"]): SourceInventory => ({ label, host: `${label}.example`, apps });

test("no collisions → no remaps, order preserved", () => {
  const plan = planConsolidation([
    src("a", [{ name: "web", port: 3000, path: "/srv/a", domains: ["a.com"], databases: ["adb"] }]),
    src("b", [{ name: "api", port: 4000, path: "/srv/b", domains: ["b.com"], databases: ["bdb"] }]),
  ]);
  assert.equal(plan.remaps.length, 0);
  assert.equal(plan.collisions.length, 0);
  assert.deepEqual(plan.order, ["a", "b"]);
});

test("port collision across sources → later app gets a free port", () => {
  const plan = planConsolidation([
    src("a", [{ name: "web", port: 3000 }]),
    src("b", [{ name: "web", port: 3000 }]),
  ]);
  assert.equal(plan.remaps.length, 1);
  assert.equal(plan.remaps[0].sourceLabel, "b");
  assert.equal(plan.remaps[0].port?.from, 3000);
  assert.equal(plan.remaps[0].port?.to, 8001); // first free in default range
  assert.equal(plan.collisions[0].kind, "port");
  assert.equal(plan.collisions[0].heldBy, "a");
});

test("port collision against the TARGET's existing ports", () => {
  const plan = planConsolidation([src("a", [{ name: "web", port: 8080 }])], { usedPorts: [8080] });
  assert.equal(plan.remaps[0].port?.from, 8080);
  assert.equal(plan.remaps[0].port?.to, 8001);
  assert.equal(plan.collisions[0].heldBy, "target");
});

