      status: copied.length ? "running" : "failed",
      detail: copied.length
        ? `MIGRATE_COPY_SSH_KEYS=1 — copied ONLY the authorized_keys file(s) for ${copied.join(", ")} (0600, owned correctly); private keys were NOT copied, so deploy keys / ops SSH access keep working`
        : `authorized_keys were found for ${withKeys.join(", ")} but the copy failed — copy each ~/.ssh/authorized_keys across by hand (0600, owned by the user)`,
    });
  } else if (withKeys.length) {
    // Some non-root users' ~/.ssh may already be on the target because their
    // whole home was rsynced (only /root/.ssh is categorically excluded). Only
    // NAME the users whose authorized_keys are genuinely absent here, so the
    // report is true.
    const missing: string[] = [];
    for (const t of sshTargets) {
      if (!withKeys.includes(t.user)) continue;
      if (await shOk(conn, `test -s ${t.home}/.ssh/authorized_keys`)) continue;
      missing.push(t.user);
    }
    if (missing.length) {
      push({
        step: `SSH authorized_keys NOT copied (${missing.join(", ")})`,
        status: "copied",
        detail: `the old server has ~/.ssh/authorized_keys for ${missing.join(", ")}; these were NOT copied (private keys are never migrated and ~/.ssh is not brought across for root), so deploy keys and ops SSH access will not carry over. Re-run with MIGRATE_COPY_SSH_KEYS=1 to copy ONLY the authorized_keys file(s), or add them by hand.`,
      });
    }
  }
}

// ---- 7. Named Docker volume data --------------------------------------

// 10d-bis. FIX WEB-2 — a HOST-level alternative reverse proxy on the SOURCE
// (Caddy / Traefik / HAProxy / Lighttpd / LiteSpeed). Containerised proxies are
// already handled in 10b; this is the host-installed case. When we generated
// our OWN nginx/apache config, that proxy's routing/TLS rules were silently
// dropped and the site would fall to the stock welcome page — so name it, one
// honest blocking step per proxy, and keep a reference copy of its config. We
// deliberately do NOT try to translate it. Re-probed LIVE (config dir OR
// binary), read-only, quote-safe (no single quotes for the source SSH channel).
if (webKind === "nginx" || webKind === "apache") {
  const altProbe = await sh(
    conn,
    onSource(
      "for prx in caddy haproxy traefik lighttpd litespeed; do h=0; " +
        "[ -d /etc/$prx ] && h=1; command -v $prx >/dev/null 2>&1 && h=1; " +
        "[ $prx = litespeed ] && { command -v lshttpd >/dev/null 2>&1 && h=1; [ -d /usr/local/lsws ] && h=1; }; " +
        "[ $h = 1 ] && echo $prx; done"
    )
  ).catch(() => ({ code: 1, stdout: "", stderr: "" }));
  const ALT_ALLOW = ["caddy", "haproxy", "traefik", "lighttpd", "litespeed"] as const;
  const NICE: Record<string, string> = {
    caddy: "Caddy",
    haproxy: "HAProxy",
    traefik: "Traefik",
    lighttpd: "Lighttpd",
    litespeed: "LiteSpeed",
  };
  const found = [
    ...new Set(
      clean(altProbe.stdout, 200)
        .split(/\s+/)
        .filter((n): n is (typeof ALT_ALLOW)[number] => (ALT_ALLOW as readonly string[]).includes(n))
    ),
  ];
  for (const prx of found) {
    // Keep a reference copy of the proxy's config (best-effort) so the step's
    // "reference copy kept at …" is true. LiteSpeed keeps its config outside
    // /etc, so both known locations are tried.
    const candidates = prx === "litespeed" ? ["/etc/litespeed", "/usr/local/lsws/conf"] : [`/etc/${prx}`];
    let refPath = refDir;
    for (const srcCfg of candidates) {
      if (await shOk(conn, onSource(`test -d ${srcCfg}`))) {
        await sh(conn, `mkdir -p ${refDir}/${prx}`);
        await sh(conn, rsyncPull(`${srcCfg}/`, `${refDir}/${prx}`), TRANSFER_TIMEOUT_MS).catch(() => {});
        refPath = `${refDir}/${prx}`;
        break;
      }
    }
    push({
      step: `Reverse proxy (${NICE[prx]}) not translated`,
      status: "copied",
      detail:
        `your site is fronted by ${NICE[prx]} on the old server; Nxeon can't translate its config, so it generated a clean ${webKind === "apache" ? "Apache" : "nginx"} config instead — your ${NICE[prx]} routing/TLS rules were NOT carried. Reference copy kept at ${refPath}.`,
    });
    await report(85, "Publishing your site…", `  Heads-up: ${NICE[prx]} fronted your site on the old server — its rules were not translated (reference copy at ${refPath}).`);
  }
}

// 10e. Wildcard / multi-tenant caveat — HTTP-01 cannot issue `*.domain`.

// ---- 11-pre. FIX OS-3a — SOURCE runs a non-systemd init ----------------
// systemd service discovery is guarded by `command -v systemctl`; on an
// OpenRC / SysV / runit / s6 source the service scan yields nothing and
// section 11 does nothing, so non-listening daemons vanish silently. Re-probe
// LIVE (read-only, quote-safe) and, when the source has NO systemd but DOES
// have init-script dirs, NAME what was not migrated. We do NOT claim the
// services were migrated — web apps are still caught by the listening-port /
// pm2 capture; daemon/worker services must be reproduced by the operator.
{
  const initProbe = await sh(
    conn,
    onSource(
      "if command -v systemctl >/dev/null 2>&1; then echo HAS_SYSTEMD; else " +
        "d=; for x in /etc/init.d /etc/service /etc/sv /etc/runlevels; do [ -d $x ] && d=\"$d $x\"; done; " +
        "s=other; " +
        "if command -v rc-status >/dev/null 2>&1 || [ -d /etc/runlevels ]; then s=OpenRC; " +
        "elif command -v sv >/dev/null 2>&1 || [ -d /etc/sv ] || [ -d /etc/runit ]; then s=runit; " +
        "elif command -v s6-rc >/dev/null 2>&1 || [ -d /etc/s6 ]; then s=s6; " +
        "elif [ -d /etc/init.d ]; then s=SysV; fi; " +
        "[ -n \"$d\" ] && echo INIT $s $d; fi"
    )
  ).catch(() => ({ code: 1, stdout: "", stderr: "" }));
  const im = /INIT\s+([A-Za-z0-9_-]{1,16})\s+(.+)/.exec(clean(initProbe.stdout, 400));
  if (im && !/HAS_SYSTEMD/.test(initProbe.stdout)) {
    const initSys = im[1];
    const initDirs = im[2].split(/\s+/).filter((d) => validPath(d)).slice(0, 8);
    if (initDirs.length) {
      push({
        step: `Services under ${initSys} init were NOT migrated`,
        status: "copied",
        detail:
          `the old server uses ${initSys} (init scripts in ${initDirs.join(", ")}), not systemd, so its services were detected but NOT recreated automatically — Nxeon migrates systemd units, and this server uses systemd. Your web apps are still caught by the listening-port / pm2 capture; reproduce any daemon/worker services from those init scripts by hand.`,
      });
      await report(90, "Re-enabling services…", `  The old server used ${initSys} (not systemd) — its services were named for you to reproduce, not migrated automatically.`);
    }
  }
}

